<?php require_once '../includes/auth.php';$slug=preg_replace('/[^a-z0-9-]/','',strtolower($_GET['slug']??''));$q=$pdo->prepare('SELECT * FROM stores WHERE slug=?');$q->execute([$slug]);$s=$q->fetch();if(!$s)exit('Store not found');$cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$ids=array_keys($cart);$in=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT * FROM products WHERE id IN($in) AND store_id=? AND available=1");$q->execute([...$ids,$s['id']]);foreach($q as $p){$p['qty']=(int)$cart[$p['id']];$p['line']=$p['qty']*$p['price'];$total+=$p['line'];$items[]=$p;}}if($_SERVER['REQUEST_METHOD']==='POST'&&$items){csrf_check();$n=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$addr=trim($_POST['address']??'');if($n&&$phone&&$addr){$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO orders(store_id,customer_name,customer_phone,customer_address,notes,total)VALUES(?,?,?,?,?,?)');$q->execute([$s['id'],$n,$phone,$addr,trim($_POST['notes']??''),$total]);$oid=$pdo->lastInsertId();$i=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity)VALUES(?,?,?,?,?)');foreach($items as $p)$i->execute([$oid,$p['id'],$p['name'],$p['price'],$p['qty']]);$pdo->commit();$_SESSION['cart']=[];$text=urlencode("Order #$oid from {$s['name']}");go('https://wa.me/'.preg_replace('/\D+/','',$s['whatsapp_number']).'?text='.$text);}$error='Complete the required fields.';}$title='Cart';require '../includes/header.php';?><h1>Cart</h1><?php foreach($items as $p):?><p><?=e($p['name'])?> × <?=e($p['qty'])?> — <?=money($p['line'])?></p><?php endforeach;?><h4>Total <?=money($total)?></h4><?php if($items):?><form method="post" class="card card-body col-lg-7"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input class="form-control mb-2" name="name" placeholder="Name" required><input class="form-control mb-2" name="phone" placeholder="Phone" required><textarea class="form-control mb-2" name="address" placeholder="Delivery address" required></textarea><textarea class="form-control mb-2" name="notes" placeholder="Notes"></textarea><button class="btn btn-success">Place order via WhatsApp</button></form><?php else:?><p>Cart is empty.</p><?php endif;?><?php require '../includes/footer.php';?>